mapper.select:
select FIN_PRODUCT.FINPROD_ID id, CONCAT_WS('',FINPROD_MARKET_ID , ':' , FINPROD_ABBR) text
from FIN_PRODUCT, FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY
where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodTypeProd}
and FIN_PRODUCT.P_FINPROD_ID IS NULL
and FIN_PRODUCT.PROFIT_TYPE = '02'

	and FIN_PRODUCT_ADD.ISSUE_STATUS = #{issueStatus}



and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID


	and (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',#{search},'%')
	or FIN_PRODUCT.FINPROD_ABBR like concat('%',#{search},'%'))


	AND FIN_PRODUCT_ADD.ISSUE_STATUS IN (#{ISSUE_STATUS_01, jdbcType = VARCHAR}, #{ISSUE_STATUS_03, jdbcType = VARCHAR})



		and FIN_PRODUCT.FINPROD_ID = #{initValue}



			and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.VDATE vdate, case when FIN_PRODUCT_ADD.DEAL_MODE in ('01', '11') then FIN_PRODUCT.MDATE when FIN_PRODUCT_ADD.DEAL_MODE in ('10', '12') and STR_TO_DATE(#{vdate}, '%Y-%m-%d') > FIN_PRODUCT.VDATE then (select FIN_OPEN_PLAN.OPEN_VDATE from FIN_OPEN_PLAN where FIN_OPEN_PLAN.FINPROD_ID = #{finprodId} and FIN_OPEN_PLAN.OPEN_TYPE IN ('01', '03') and STR_TO_DATE(#{vdate}, '%Y-%m-%d') >= FIN_OPEN_PLAN.OPEN_DATE_STR and FIN_OPEN_PLAN.OPEN_DATE_END >= STR_TO_DATE(#{vdate}, '%Y-%m-%d')) when FIN_PRODUCT_ADD.DEAL_MODE in ('10', '12') and FIN_PRODUCT.VDATE >= STR_TO_DATE(#{vdate}, '%Y-%m-%d') then (select * from (select FIN_OPEN_PLAN.OPEN_VDATE from FIN_OPEN_PLAN where FIN_OPEN_PLAN.FINPROD_ID = #{finprodId} and FIN_OPEN_PLAN.OPEN_TYPE IN ('01', '03') order by OPEN_MDATE) where LIMIT 1) else null end mdate, FIN_PRODUCT_ADD.TMPL_ID tmplId, FIN_PRODUCT.FINPROD_NAME finprodName, FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
FIN_PRODUCT_ADD.PORTFOLIO_ID ptlId, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT.OPERATION_TYPE operationType,
FIN_RATE_INFO.INT_TYPE calcType, FIN_PRODUCT_ADD.IS_CYCLE isCycle, FIN_PRODUCT_ADD.IS_LAY isLay, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT_ADD.INVESTMENT_CYCLE investmentCycle, FIN_PRODUCT_ADD.LAY_TYPE layType, FIN_PRODUCT_ADD.PROFIT_FLAG profitFlag, FIN_PRODUCT.ENTRUST_TYPE entrustType, FIN_PRODUCT.ENTRUSTER entruster, FIN_RATE_INFO.RATE * 100 yield, PRD_SALE_PARAM.FIRST_SALE_VDATE firstSaleVdate, PRD_SALE_PARAM.FIRST_SALE_MDATE firstSaleMdate, PRD_SALE_PARAM.CONTINUE_FLAG continueFlag, FIN_PRODUCT_ADD.CLOSE_DAYS closeDays, FIN_PRODUCT.TERM_DAYS termDays, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_RATE_INFO.BASIS basis, FIN_PRODUCT.CCY ccy, FIN_PRODUCT_ADD.SALE_DEPARTMENT saleDepartment, FIN_PRODUCT_ADD.PUR_SPEED purSpeed, FIN_PRODUCT.ISSUE_TYPE issueType, FIN_PRODUCT_ADD.INVEST_NATURE investNature, FIN_PRODUCT_ADD.SALE_MODE saleMode,
case when (select count(*) from TRD_FIN_PRODUCT_DEAL_TOTAL where FINPROD_ID = #{finprodId})>0 then 'C2' else 'C1' end ps from FIN_PRODUCT left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = #{branch}
left join FIN_RATE_INFO on FIN_CASH_INFO.CASH_ID = FIN_RATE_INFO.CASH_ID and (FIN_PRODUCT.VDATE IS NULL OR FIN_RATE_INFO.EFF_DATE = FIN_PRODUCT.VDATE) left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.FINPROD_ID = #{finprodId}
and FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodMarketId}
